mapper.select:
SELECT resultdata.*, a1.AREA_NAME AS provinceName, a2.AREA_NAME AS cityName, a3.AREA_NAME AS countryName FROM ( SELECT m.id, m.device_code, d.device_name, m.creator, m.create_time, d.province_id, d.city_id, d.county_id, d.device_status, d.location as deviceAddress FROM vm_water_level_info_t m, vm_device_info_t d, vm_order_devices t WHERE t.device_code = d.device_code AND m.device_code = d.device_code AND m.tenant_id = t.tenant_id AND m.industry_code = t.industry_code AND m.delete_flag = 0 AND d.delete_flag = '0' AND t.delete_flag = 0 AND t.ord_status IN ( 0, 1, 2 ) ${dataScope}
AND m.device_code like CONCAT('%', #{deviceCode}, '%')
AND d.device_status = #{deviceStatus}
AND d.device_name like CONCAT('%', #{deviceName}, '%')
AND d.province_id = #{provinceId}
AND d.city_id = #{cityId}
AND d.county_id = #{countryId}
AND m.id IN
#{labelIdItem}
) resultdata LEFT JOIN sys_area a1 ON a1.AREA_CODE = resultdata.province_id LEFT JOIN sys_area a2 ON a2.AREA_CODE = resultdata.city_id LEFT JOIN sys_area a3 ON a3.AREA_CODE = resultdata.county_id
